const assert=require("node:assert/strict"),fs=require("fs"),crypto=require("crypto");(async()=>{const origin="https://iwantsexnow.ch";const results=[];async function req(path,status=200,init={}){const r=await fetch(origin+path,{redirect:"manual",signal:AbortSignal.timeout(20000),...init});assert.equal(r.status,status,path);results.push({path,method:init.method||"GET",status:r.status,robots:r.headers.get("x-robots-tag"),cache:r.headers.get("cache-control")});return r;}const publicState=await(await req("/api/vault/metrics")).json();assert.deepEqual(publicState,{ok:true,metrics:{},states:{},measurementStatus:"unavailable"});const home=await(await req("/")).text();const next=JSON.parse(home.match(/<script id="__NEXT_DATA__" type="application\/json">([\s\S]+?)<\/script>/)[1]);const fingerprint={buildId:next.buildId,deploymentId:home.match(/dpl_[A-Za-z0-9]+/)?.[0]};for(const path of ["/","/search","/escort-zurich","/escort-basel","/orte/cham","/reviews","/reviews/xdate-review","/report","/privacy","/contact","/imprint"]){const r=await req(path);assert.match(r.headers.get("x-robots-tag")||"",/noindex/);const html=await r.text();const expected=origin+(path==="/"?"":path);assert.ok(html.includes('rel="canonical" href="'+expected+'"'),path+" canonical");assert.ok(html.includes('property="og:url" content="'+expected+'"'),path+" og:url");assert.doesNotMatch(html,/hreflang=/i);}const policy=JSON.parse(fs.readFileSync("docs/goal/release-policy.json","utf8"));for(const route of policy.gatedRoutes){const r=await req("/"+route);const html=await r.text();assert.ok(html.includes("noch nicht freigeschaltet"),route);assert.doesNotMatch(html,/<form\b|type="password"/i);}for(const path of ["/profile/does-not-exist","/profile/ch-9999999","/profile/pilot-zh-1","/profile/w4-1","/orte/not-a-place","/reviews/not-a-report","/guides/not-a-guide","/catalogue/demo-zurich-escort","/catalogue/not-a-demo-id"])await req(path,404);for(const path of ["/api/admin/overview","/api/indexer/import"])await req(path,401);const search=await(await req("/api/vault/search?page=1&limit=48")).json();assert.deepEqual(search.results,[]);assert.equal(search.totalMatches,0);assert.equal(search.status,"ok");await req("/api/vault/search?page=NaN",400);await req("/api/vault/search?q=a&q=b",400);const sitemap=await(await req("/sitemap.xml")).text();assert.doesNotMatch(sitemap,/<loc>|<lastmod>/);for(const [path,body,status] of [["/api/vault/metrics",{action:"unknown"},400],["/api/vault/metrics",{action:"claim_or_create_profile",profileId:"ch-1",ownerToken:"revoked-public-token"},410],["/api/vault/metrics",{action:"update_profile_fields",profileId:"ch-1",identityVerified:true},410],["/api/vault/metrics",{action:"report_or_optout",details:"synthetic acceptance probe; must not be stored"},410],["/api/claims/create",{},410],["/api/enquiries/create",{},410]]){const r=await req(path,status,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)});assert.equal((await r.json()).ok,false);assert.match(r.headers.get("cache-control")||"",/no-store/);}for(const [method,data,status,authorization] of [["GET",null,405],["POST",{function:"../admin",payload:{}},400],["POST",{function:"scheduled-screenshots",payload:{}},400],["POST",{function:"fetch-html",payload:{url:"https://example.org"}},401],["POST",{function:"firecrawl-map",payload:{}},401,"Bearer bad"]]){const r=await req("/api/supabase-function",status,{method,headers:{"Content-Type":"application/json",...(authorization?{Authorization:authorization}:{})},body:data?JSON.stringify(data):undefined});assert.match(r.headers.get("cache-control")||"",/no-store/);}for(const [path,method]of [["/private/provider-draft","GET"],["/api/private/provider-session","GET"],["/api/private/provider-session","POST"],["/api/private/provider-drafts","GET"],["/api/private/provider-drafts","POST"],["/api/private/provider-drafts","PUT"]]){const r=await req(path,404,{method,headers:{Origin:origin,"Content-Type":"application/json"},body:method==="GET"?undefined:"{}"});assert.match(r.headers.get("cache-control")||"",/no-store/);assert.match(r.headers.get("x-robots-tag")||"",/noindex/);await r.text();}const localApp=fs.readdirSync(".next/static/chunks/pages").find(n=>/^_app-.+\.js$/.test(n));const assetPath="/_next/static/chunks/pages/"+localApp;const deployed=await req(assetPath);const asset=Buffer.from(await deployed.arrayBuffer());const hash=x=>crypto.createHash("sha256").update(x).digest("hex");assert.equal(hash(asset),hash(fs.readFileSync(".next/static/chunks/pages/"+localApp)));const report={dateZurich:"2026-10-26",origin,sourceCommit:"e08451b5c0ec969df720a00309195978da28eb1b",sourceTree:"a646abac25f6c3b17c6cddb269ccb89dca3e1f43",fingerprint,appBundle:{path:assetPath,sha256:hash(asset),matchesManagedBuild:true},checks:results.length,passed:true,results};fs.writeFileSync("/tmp/iwsn-p0-live-acceptance.json",JSON.stringify(report,null,2));console.log(JSON.stringify({passed:true,checks:results.length,fingerprint,appBundle:report.appBundle},null,2));})().catch(e=>{fs.writeFileSync("/tmp/iwsn-p0-live-acceptance.json",JSON.stringify({passed:false,message:e.message},null,2));console.error("LIVE_ACCEPTANCE_FAILED:",e.message);process.exitCode=1;});
